use serde::{Deserialize,Serialize};use std::{sync::{Arc,Mutex,atomic::{AtomicUsize,Ordering}},thread,time::{Duration,Instant},net::{TcpStream,ToSocketAddrs}};
#[derive(Deserialize)]struct Check{id:String,kind:String,#[serde(default)]url:String,#[serde(default)]host:String,#[serde(default)]port:u16}
#[derive(Deserialize)]struct Spec{checks:Vec<Check>,#[serde(default)]ca:String}
#[derive(Serialize)]struct Row{id:String,status:&'static str,latency_ms:Option<u128>,#[serde(skip_serializing_if="Option::is_none")]http_code:Option<u16>}
fn local(s:&str)->bool{matches!(s,"127.0.0.1"|"localhost"|"::1"|"[::1]")}
fn probe(c:&Check,client:&reqwest::blocking::Client,tls:&native_tls::TlsConnector)->Row{
 let t=Instant::now();let mut code=None;let status=match c.kind.as_str(){
 "http"|"http_gateway"=>{let res=reqwest::Url::parse(&c.url).ok().filter(|u|u.host_str().is_some_and(local)&&u.username().is_empty()&&u.password().is_none()&&matches!(u.scheme(),"http"|"https")).and_then(|u|client.get(u).send().ok());match res{Some(r)=>{let n=r.status().as_u16();code=Some(n);match n{200..=399=>"ok",401|403|404|429=>"degraded",500..=599=>"down",_=>"unknown"}},None=>"down"}}
 "tcp_tls"=>{let ok=local(&c.host)&&(&*c.host,c.port).to_socket_addrs().ok().into_iter().flatten().any(|a|TcpStream::connect_timeout(&a,Duration::from_secs(2)).ok().and_then(|s|{s.set_read_timeout(Some(Duration::from_secs(2))).ok()?;s.set_write_timeout(Some(Duration::from_secs(2))).ok()?;tls.connect(&c.host,s).ok()}).is_some());if ok{"ok"}else{"down"}}
 "music_ynison"=>"disabled",_=>"unsupported"};
 Row{id:c.id.clone(),status,latency_ms:if matches!(status,"unsupported"|"disabled"){None}else{Some(t.elapsed().as_millis())},http_code:code}
}
fn main(){let f=std::env::args().nth(1).expect("offline fixture path");let spec:Spec=serde_json::from_str(&std::fs::read_to_string(f).unwrap()).unwrap();let mut cb=reqwest::blocking::Client::builder().no_proxy().timeout(Duration::from_secs(2)).redirect(reqwest::redirect::Policy::custom(|a|{if a.previous().len()>=10||!a.url().host_str().is_some_and(local){a.error("unsafe redirect")}else{a.follow()}}));let mut tb=native_tls::TlsConnector::builder();tb.min_protocol_version(Some(native_tls::Protocol::Tlsv12));if !spec.ca.is_empty(){cb=cb.add_root_certificate(reqwest::Certificate::from_pem(spec.ca.as_bytes()).unwrap());tb.add_root_certificate(native_tls::Certificate::from_pem(spec.ca.as_bytes()).unwrap());}let client=cb.build().unwrap();let tls=tb.build().unwrap();let out=Arc::new(Mutex::new(Vec::new()));let next=AtomicUsize::new(0);thread::scope(|s|{for _ in 0..8{let out=out.clone();let (next,checks,client,tls)=(&next,&spec.checks,&client,&tls);s.spawn(move ||loop{let i=next.fetch_add(1,Ordering::Relaxed);let Some(c)=checks.get(i)else{break};let r=probe(c,client,tls);out.lock().unwrap().push((i,r));});}});let mut rows=Arc::try_unwrap(out).ok().unwrap().into_inner().unwrap();rows.sort_by_key(|r|r.0);println!("{}",serde_json::json!({"schema":1,"results":rows.into_iter().map(|r|r.1).collect::<Vec<_>>()}));}
